import json
import subprocess
from pathlib import Path

root = Path('/tmp/slope-pr-essence')
proposals = json.loads((root / 'proposals.json').read_text())
results = []

def api(endpoint, method='GET', payload=None):
    args = ['gh', 'api', endpoint, '--method', method]
    data = None
    if payload is not None:
        args += ['--input', '-']
        data = json.dumps(payload)
    return json.loads(subprocess.check_output(args, input=data, text=True))

for item in proposals:
    endpoint = f'repos/owassmer/Slope_Sparse_Events/' + (f'pulls/{item["id"]}' if item['kind'] == 'pr' else f'issues/comments/{item["id"]}')
    live = api(endpoint)
    if live['body'] != item['old_body'] or (item['kind'] == 'pr' and live['title'] != item['old_title']):
        results.append({'kind': item['kind'], 'id': item['id'], 'status': 'concurrent_change', 'live': live})
        print(f'Skipped concurrent change: {item["kind"]} {item["id"]}', flush=True)
    else:
        payload = {'body': item['body']}
        if item['kind'] == 'pr':
            payload['title'] = item['title']
        updated = api(endpoint, 'PATCH', payload)
        assert updated['body'] == item['body']
        if item['kind'] == 'pr':
            assert updated['title'] == item['title']
        results.append({'kind': item['kind'], 'id': item['id'], 'status': 'updated', 'url': item['url']})
    (root / 'results.json').write_text(json.dumps(results, indent=2))
    if len(results) % 10 == 0:
        print(f'Processed {len(results)}/{len(proposals)}', flush=True)
print('Complete:', len(results), 'items', flush=True)

